/* ============================================
   GreenBean Coffee — Design System
   ============================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap');

/* --- Design Tokens --- */
:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-hover: #006B3E;
  --green-light: #E8F5ED;
  --green-lighter: #F0FAF4;
  --green-dark: #1E3932;
  --green-forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6E3;
  --cream-dark: #E8C97A;

  /* Neutrals */
  --brown: #6F4E37;
  --brown-light: #A67B5B;
  --brown-dark: #3E2723;
  --surface: #FAFAF7;
  --surface-warm: #F7F4EF;
  --surface-alt: #F2EFE8;
  --white: #FFFFFF;
  --text-primary: #1A1A1A;
  --text-secondary: #5C5C5C;
  --text-tertiary: #8C8C8C;
  --border: #E5E0D8;
  --border-light: #F0ECE4;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.1), 0 4px 8px rgba(0,0,0,0.06);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.12);

  /* Typography */
  --font-display: 'DM Serif Display', Georgia, serif;
  --font-body: 'DM Sans', system-ui, sans-serif;

  /* Spacing */
  --container: 1280px;
  --section-py: 80px;
  --section-px: 24px;

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* --- Reset --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

input, select, textarea {
  font-family: inherit;
  font-size: 16px;
}

/* --- Typography --- */
.font-display {
  font-family: var(--font-display);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  line-height: 1.15;
  color: var(--text-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 3.75rem); }
h2 { font-size: clamp(2rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.5rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

p {
  line-height: 1.65;
  color: var(--text-secondary);
}

/* --- Layout --- */
.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.section {
  padding: var(--section-py) 0;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 48px;
}

.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--green-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn-outline:hover {
  background: var(--green-light);
}

.btn-dark {
  background: var(--green-dark);
  color: var(--white);
}

.btn-dark:hover {
  background: var(--green-forest);
  transform: translateY(-1px);
}

.btn-cream {
  background: var(--cream);
  color: var(--brown-dark);
}

.btn-cream:hover {
  background: var(--cream-dark);
}

.btn-white {
  background: var(--white);
  color: var(--green-dark);
}

.btn-white:hover {
  background: var(--surface);
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
  min-height: 40px;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1rem;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--border-light);
  transition: box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--green-primary);
  font-weight: 400;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.header-nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
  position: relative;
}

.header-nav a:hover {
  color: var(--green-primary);
}

.header-nav a.active {
  color: var(--green-primary);
}

.header-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green-primary);
  border-radius: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header-actions .btn {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.find-store-link {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
}

.find-store-link:hover {
  color: var(--green-primary);
}

.mobile-menu-btn {
  display: none;
  padding: 8px;
  color: var(--text-primary);
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
}

/* --- Mobile Navigation --- */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 200;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.mobile-nav-overlay.active {
  opacity: 1;
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: 0;
  width: 320px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 201;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  padding: 24px;
  overflow-y: auto;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-close {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-bottom: 24px;
}

.mobile-nav-close button {
  padding: 8px;
  color: var(--text-primary);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mobile-nav-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border-light);
}

.mobile-nav-links a svg {
  width: 20px;
  height: 20px;
  color: var(--text-tertiary);
}

.mobile-nav-actions {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.mobile-nav-actions .btn {
  width: 100%;
  justify-content: center;
}

/* --- Footer --- */
.site-footer {
  background: var(--green-dark);
  color: rgba(255,255,255,0.85);
  padding: 56px 0 32px;
}

.footer-inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.12);
}

.footer-col h4 {
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: 16px;
  letter-spacing: 0.02em;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}

.footer-social a:hover {
  color: var(--white);
}

.footer-social svg {
  width: 20px;
  height: 20px;
}

/* Footer Accordion (Mobile) */
.footer-accordion-btn {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--white);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}

.footer-accordion-btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

.footer-accordion-btn.expanded svg {
  transform: rotate(180deg);
}

.footer-col-links {
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 20px;
  max-width: 900px;
  width: calc(100% - 48px);
  z-index: 300;
  box-shadow: var(--shadow-xl);
  animation: cookieSlideUp 0.5s ease-out 0.5s both;
}

.cookie-banner.hidden {
  display: none;
}

.cookie-banner-text {
  flex: 1;
}

.cookie-banner-text h4 {
  color: var(--cream);
  font-family: var(--font-display);
  font-size: 1.0625rem;
  margin-bottom: 4px;
}

.cookie-banner-text p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.8);
  line-height: 1.5;
}

.cookie-banner-actions {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}

@keyframes cookieSlideUp {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

/* --- Animations --- */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.stagger-1 { transition-delay: 0.1s; }
.stagger-2 { transition-delay: 0.2s; }
.stagger-3 { transition-delay: 0.3s; }
.stagger-4 { transition-delay: 0.4s; }

/* --- Card Styles --- */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16/9;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-body {
  padding: 20px;
}

.card-body h3 {
  margin-bottom: 8px;
}

.card-body p {
  font-size: 0.9375rem;
  margin-bottom: 16px;
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 0;
  font-size: 0.875rem;
  color: var(--text-tertiary);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-tertiary);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-direction: column;
}

.tab-list {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid var(--border-light);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-trigger {
  padding: 14px 20px;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.tab-trigger:hover {
  color: var(--green-primary);
}

.tab-trigger.active {
  color: var(--green-primary);
  border-bottom-color: var(--green-primary);
}

.tab-content {
  display: none;
  padding: 28px 0;
  animation: tabFadeIn 0.3s ease;
}

.tab-content.active {
  display: block;
}

@keyframes tabFadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-slide {
  flex: 0 0 auto;
  scroll-snap-align: start;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  z-index: 10;
  transition: all var(--transition-fast);
  border: 1px solid var(--border);
}

.carousel-btn:hover {
  background: var(--green-light);
  color: var(--green-primary);
  border-color: var(--green-primary);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-btn-prev {
  left: -8px;
}

.carousel-btn-next {
  right: -8px;
}

/* --- Gift Card --- */
.gift-card {
  width: 200px;
  height: 130px;
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.8125rem;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  border: 2px solid transparent;
}

.gift-card:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: var(--shadow-lg);
  border-color: var(--green-primary);
}

.gift-card-label {
  position: relative;
  z-index: 1;
  text-align: center;
  padding: 8px;
}

/* --- Map Placeholder --- */
.map-placeholder {
  width: 100%;
  height: 420px;
  background: var(--surface-alt);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--text-tertiary);
  position: relative;
  overflow: hidden;
}

.map-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 40%, var(--green-light) 0%, transparent 50%),
    radial-gradient(circle at 70% 60%, var(--cream-light) 0%, transparent 40%);
  opacity: 0.5;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  position: relative;
  z-index: 1;
}

.map-placeholder span {
  position: relative;
  z-index: 1;
  font-weight: 500;
}

.map-pins {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.map-pin {
  position: absolute;
  width: 28px;
  height: 28px;
  transform: translate(-50%, -100%);
}

.map-pin svg {
  width: 28px;
  height: 28px;
  fill: var(--green-primary);
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));
}

/* --- Store Card --- */
.store-card {
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 20px;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h4 {
  font-family: var(--font-body);
  font-weight: 600;
  margin-bottom: 6px;
}

.store-card .store-address {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.store-card .store-hours {
  font-size: 0.8125rem;
  color: var(--green-primary);
  font-weight: 500;
  margin-bottom: 12px;
}

.store-card .store-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.store-feature-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background: var(--green-lighter);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 500;
}

/* --- Section Backgrounds --- */
.bg-green-dark {
  background: var(--green-dark);
  color: var(--white);
}

.bg-green-dark h2, .bg-green-dark h3, .bg-green-dark h4 {
  color: var(--white);
}

.bg-green-dark p {
  color: rgba(255,255,255,0.8);
}

.bg-cream {
  background: var(--cream-light);
}

.bg-surface {
  background: var(--surface);
}

.bg-surface-warm {
  background: var(--surface-warm);
}

/* --- Hero Section Variants --- */
.hero-section {
  position: relative;
  overflow: hidden;
  padding: 80px 0;
  min-height: 500px;
  display: flex;
  align-items: center;
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background:
