  --green-forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF6E3;
  --cream-dark: #E8C97A;

  /* Neutrals */
  --brown: #6F4E37;
  --brown-light: #A67B5B;
  --brown-dark: #3E2723;
  --surface: #FAFAF7;
  --surface-warm: #F7F4EF;
  --surface-alt: #F2EFE8;
  --white: #FFFFFF;
  --text-primary: #1A1A1A;
  --text-secondary: #5C5C5C;
  --text-tertiary: #8C8C8C;
  --border: #E5E0D8;
  --border-light: #F0ECE4;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.1), 0 4px 8px rgba(0,0,0,0.06);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.12);

  /* Typography */
  --font-display: 'DM Serif Display', Georgia, serif;
  --font-body: 'DM Sans', system-ui, sans-serif;

  /* Spacing */
  --container: 1280px;
  --section-py: 80px;
  --section-px: 24px;

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* --- Reset --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

input, select, textarea {
  font-family: inherit;
  font-size: 16px;
}

/* --- Typography --- */
.font-display {
  font-family: var(--font-display);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  line-height: 1.15;
  color: var(--text-primary);
}

h1 { font-size: clamp(2.5rem, 5vw, 3.75rem); }
h2 { font-size: clamp(2rem, 3.5vw, 2.75rem); }
h3 { font-size: clamp(1.5rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

p {
  line-height: 1.65;
  color: var(--text-secondary);
}

/* --- Layout --- */
.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.section {
  padding: var(--section-py) 0;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
  min-height: 48px;
}

.btn-primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--green-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn-outline:hover {
  background: var(--green-light);
}

.btn-dark {
  background: var(--green-dark);
  color: var(--white);
}

.btn-dark:hover {
  background: var(--green-forest);
  transform: translateY(-1px);
}

.btn-cream {
  background: var(--cream);
  color: var(--brown-dark);
}

.btn-cream:hover {
  background: var(--cream-dark);
}

.btn-white {
  background: var(--white);
  color: var(--green-dark);
}

.btn-white:hover {
  background: var(--surface);
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
  min-height: 40px;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1rem;
}

/* --- Header --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--border-light);
  transition: box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--green-primary);
  font-weight: 400;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.header-nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
  position: relative;
}

.header-nav a:hover {
  color: var(--green-primary);
}

.header-nav a.active {
  color: var(--green-primary);
}

.header-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green-primary);
  border-radius: 1px;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header-actions .btn {
  padding: 10px 20px;
  font-size: 0.875rem;
}

.find-store-link {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: color var(--transition-fast);
}

.find-store-link:hover {
  color: var(--green-primary);
}

.mobile-menu-btn {
  display: none;
  padding: 8px;
  color: var(--text-primary);
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
}

/* --- Mobile Navigation --- */
.mobile-nav-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.4);
  z-index: 200;
  opacity: 0;
  transition: opacity var(--transition-base);
}

.mobile-nav-overlay.active {
  opacity: 1;
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: 0;
  width: 320px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 201;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  padding: 24px;
  overflow-y: auto;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-close {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-bottom: 24px;
}

.mobile-nav-close button {
  padding: 8px;
  color: var(--text-primary);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mobile-nav-links a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border-light);
}

.mobile-nav-links a svg {
  width: 20px;
  height: 20px;
  color: var(--text-tertiary);
}

.mobile-nav-actions {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.mobile-nav-actions .btn {
  width: 100%;
  justify-content: center;
}

/* --- Footer --- */
.site-footer {
  background: var(--green-dark);
  color: rgba(255,255,255,0.85);
  padding: 56px 0 32px;
}

.footer-inner {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--section-px);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.12);
}

.footer-col h4 {
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  margin-bottom: 16px;
  letter-spacing: 0.02em;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}

.footer-social a:hover {
  color: var(--white);
}

.footer-social svg {
  width: 20px;
  height: 20px;
}

/* Footer Accordion (Mobile) */
.footer-accordion-btn {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--white);
  border-bottom: 1px solid rgba(255,255,255,0.12);
}

.footer-accordion-btn svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-base);
}

.footer-accordion-btn.expanded svg {
  transform: rotate(180deg);
}

.footer-col-links {
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 20px;
  max-width: 900px;
  width: calc(100% - 48px);
  z-index: 300;
  box-shadow: var(--shadow-xl);
  animation: cookieSlideUp 0.5s ease-out 0.5s both;
}

.cookie-banner.hidden {
  display: none;
}

.cookie-banner-text {
  flex: 1;
}

.cookie-banner-text h4 {
  color: var(--cream);
  font-family: var(--font-display);
  font-size: 1.0625rem;
  margin-bottom: 4px;
}

.cookie-banner-text p {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.8);
  line-height: 1.5;
}

.cookie-banner-actions {
  display: flex;
  gap: 10px;
  flex-shrink: 0;
}

@keyframes cookieSlideUp {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

/* --- Animations --- */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.stagger-1 { transition-delay: 0.1s; }
.stagger-2 { transition-delay: 0.2s; }
.stagger-3 { transition-delay: 0.3s; }
.stagger-4 { transition-delay: 0.4s; }

/* --- Card Styles --- */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16/9;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-body {
  padding: 20px;
}

.card-body h3 {
  margin-bottom: 8px;
}

.card-body p {
  font-size: 0.9375rem;
  margin-bottom: 16px;
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 0;
  font-size: 0.875rem;
  color: var(--text-tertiary);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb .separator {
  color: var(--text-tertiary);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-direction: column;
}

.tab-list {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid var(--border-light);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.tab-list::-webkit-scrollbar {
  display: none;
}

.tab-trigger {
  padding: 14px 20px;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.tab-trigger:hover {
  color: var(--green-primary);
}

.tab-trigger.active {
  color: var(--green-primary);
  border-bottom-color: var(--green-primary);
}

.tab-content {
  display: none;
  padding: 28px 0;
  animation: tabFadeIn 0.3s ease;
}

.tab-content.active {
  display: block;
}

@keyframes tabFadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 8px 0;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-slide {
  flex: 0 0 auto;
  scroll-snap-align: start;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  z-index: 10;
  transition: all var(--transition-fast);
  border: 1px solid var(--border);
}

.carousel-btn:hover {
  background: var(--green-light);
  color: var(--green-primary);
  border-color: var(--green-primary);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

.carousel-btn-prev {
  left: -8px;
}

.carousel-btn-next {
  right: -8px;
}

/* --- Gift Card --- */
.gift-card {
  width: 200px;
  height: 130px;
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.8125rem;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  border: 2px solid transparent;
}

.gift-card:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: var(--shadow-lg);
  border-color: var(--green-primary);
}

.gift-card-label {
  position: relative;
  z-index: 1;
  text-align: center;
  padding: 8px;
}

/* --- Map Placeholder --- */
.map-placeholder {
  width: 100%;
  height: 420px;
  background: var(--surface-alt);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--text-tertiary);
  position: relative;
  overflow: hidden;
}

.map-placeholder::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 40%, var(--green-light) 0%, transparent 50%),
    radial-gradient(circle at 70% 60%, var(--cream-light) 0%, transparent 40%);
  opacity: 0.5;
}

.map-placeholder svg {
  width: 48px;
  height: 48px;
  position: relative;
  z-index: 1;
}

.map-placeholder span {
  position: relative;
  z-index: 1;
  font-weight: 500;
}

.map-pins {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.map-pin {
  position: absolute;
  width: 28px;
  height: 28px;
  transform: translate(-50%, -100%);
}

.map-pin svg {
  width: 28px;
  height: 28px;
  fill: var(--green-primary);
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));
}

/* --- Store Card --- */
.store-card {
  background: var(--white);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 20px;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.store-card h4 {
  font-family: var(--font-body);
  font-weight: 600;
  margin-bottom: 6px;
}

.store-card .store-address {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.store-card .store-hours {
  font-size: 0.8125rem;
  color: var(--green-primary);
  font-weight: 500;
  margin-bottom: 12px;
}

.store-card .store-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.store-feature-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  background: var(--green-lighter);
  color: var(--green-primary);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 500;
}

/* --- Section Backgrounds --- */
.bg-green-dark {
  background: var(--green-dark);
  color: var(--white);
}

.bg-green-dark h2, .bg-green-dark h3, .bg-green-dark h4 {
  color: var(--white);
}

.bg-green-dark p {
  color: rgba(255,255,255,0.8);
}

.bg-cream {
  background: var(--cream-light);
}

.bg-surface {
  background: var(--surface);
}

.bg-surface-warm {
  background: var(--surface-warm);
}

/* --- Hero Section Variants --- */
.hero-section {
  position: relative;
  overflow: hidden;
  padding: 80px 0;
  min-height: 500px;
  display: flex;
  align-items: center;
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(0,130,74,0.08) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 30%, rgba(243,206,161,0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 100%, rgba(0,130,74,0.05) 0%, transparent 40%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}

.hero-title {
  font-size: clamp(2.75rem, 5.5vw, 4rem);
  line-height: 1.05;
  margin-bottom: 20px;
  color: var(--green-dark);
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: 28px;
  max-width: 480px;
}

.hero-image {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 45%;
  max-width: 550px;
  z-index: 1;
}

.hero-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--green-light) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero-image-placeholder::after {
  content: '';
  position: absolute;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0,130,74,0.15) 0%, transparent 70%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

/* --- Promo Section (split layout) --- */
.promo-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: stretch;
}

.promo-card {
  border-radius: var(--radius-xl);
  overflow: hidden;
  position: relative;
  min-height: 360px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  transition: transform var(--transition-base);
}

.promo-card:hover {
  transform: scale(1.005);
}

.promo-card-image {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.promo-card-image .placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.promo-card-content {
  position: relative;
  z-index: 1;
  padding: 32px;
}

.promo-card-content h2 {
  margin-bottom: 12px;
}

.promo-card-content p {
  margin-bottom: 20px;
}

/* --- Menu Sidebar --- */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 32px 0;
}

.menu-sidebar {
  position: sticky;
  top: 88px;
  align-self: start;
  max-height: calc(100vh - 104px);
  overflow-y: auto;
  padding-right: 16px;
}

.menu-sidebar-group {
  margin-bottom: 24px;
}

.menu-sidebar-group h3 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-tertiary);
  margin-bottom: 8px;
  padding-left: 12px;
}

.menu-sidebar-item {
  display: block;
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.menu-sidebar-item:hover {
  background: var(--green-lighter);
  color: var(--green-primary);
}

.menu-sidebar-item.active {
  background: var(--green-light);
  color: var(--green-primary);
  font-weight: 600;
}

.menu-content h2 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--border-light);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
  margin-bottom: 48px;
}

.menu-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px;
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
  cursor: pointer;
}

.menu-item:hover {
  background: var(--surface);
}

.menu-item-img {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--surface-alt);
  flex-shrink: 0;
  overflow: hidden;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.9375rem;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-tertiary);
}

/* --- Rewards --- */
.rewards-hero {
  background: var(--green-dark);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 30% 80%, rgba(0,130,74,0.2) 0%, transparent 50%),
    radial-gradient(ellipse at 70% 20%, rgba(243,206,161,0.1) 0%, transparent 50%);
}

.rewards-hero .container {
  position: relative;
  z-index: 1;
}

.rewards-hero h1 {
  color: var(--white);
  margin-bottom: 16px;
}

.rewards-hero p {
  color: rgba(255,255,255,0.8);
  max-width: 500px;
  margin: 0 auto 28px;
}

.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.how-it-works-step {
  padding: 32px 24px;
}

.how-it-works-step .step-number {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--green-primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1.125rem;
  margin: 0 auto 20px;
}

.how-it-works-step h3 {
  margin-bottom: 10px;
  font-size: 1.25rem;
}

.tier-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid var(--border-light);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  position: relative;
}

.tier-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
}

.tier-card.highlighted {
  border-color: var(--green-primary);
  background: linear-gradient(to bottom, var(--green-lighter), var(--white));
}

.tier-card .tier-name {
  font-family: var(--font-display);
  font-size: 1.5rem;
  margin-bottom: 4px;
}

.tier-card .tier-stars {
  font-size: 0.875rem;
  color: var(--green-primary);
  font-weight: 600;
  margin-bottom: 16px;
}

.tier-card .tier-benefits {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tier-card .tier-benefit {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.tier-card .tier-benefit svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  margin-top: 3px;
  color: var(--green-primary);
}

.redemption-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}

.redemption-item {
  text-align: center;
  padding: 24px 16px;
  background: var(--surface);
  border-radius: var(--radius-md);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.redemption-item:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.redemption-item .stars {
  font-family: var(--font-display);
  font-size: 1.75rem;
  color: var(--green-primary);
  margin-bottom: 8px;
}

.redemption-item .reward {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.redemption-item .value {
  font-size: 0.8125rem;
  color: var(--text-tertiary);
}

/* --- Store Locator --- */
.store-search {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
  align-items: stretch;
}

.store-search-input {
  flex: 1;
  position: relative;
}

.store-search-input input {
  width: 100%;
  padding: 14px 16px 14px 44px;
  border: 2px solid var(--border);
  border-radius: var(--radius-full);
  font-size: 1rem;
  transition: border-color var(--transition-fast);
  background: var(--white);
}

.store-search-input input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.store-search-input svg {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--text-tertiary);
}

.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  margin-top: 4px;
  display: none;
  z-index: 50;
  overflow: hidden;
}

.search-suggestions.active {
  display: block;
}

.search-suggestion {
  padding: 12px 16px;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 10px;
}

.search-suggestion:hover {
  background: var(--green-lighter);
}

.search-suggestion svg {
  width: 16px;
  height: 16px;
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.order-toggle {
  display: flex;
  background: var(--surface);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: 24px;
  width: fit-content;
}

.order-toggle-btn {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.order-toggle-btn.active {
  background: var(--green-primary);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  border: 2px solid var(--border);
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  background: var(--white);
}

.filter-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.filter-btn.active {
  border-color: var(--green-primary);
  background: var(--green-lighter);
  color: var(--green-primary);
}

.filter-panel {
  display: none;
  background: var(--surface);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 24px;
}

.filter-panel.active {
  display: block;
  animation: tabFadeIn 0.3s ease;
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.filter-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: all var(--transition-fast);
  background: var(--white);
}

.filter-chip:hover, .filter-chip.selected {
  border-color: var(--green-primary);
  background: var(--green-lighter);
  color: var(--green-primary);
}

.store-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.store-results {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 8px;
}

/* --- Partnership Card --- */
.partner-card {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-light);
  transition: box-shadow var(--transition-base);
}

.partner-card:hover {
  box-shadow: var(--shadow-md);
}

.partner-logo {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.partner-info h4 {
  font-family: var(--font-body);
  margin-bottom: 4px;
}

.partner-info p {
  font-size: 0.875rem;
}

/* --- App Download --- */
.app-download-section {
  background: linear-gradient(135deg, var(--green-dark) 0%, var(--green-forest) 100%);
  padding: 60px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.app-download-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(243,206,161,0.08) 0%, transparent 70%);
}

.app-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-top: 24px;
}

.app-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.app-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.app-btn svg {
  width: 24px;
  height: 24px;
}

.app-btn span {
  text-align: left;
  font-size: 0.6875rem;
  color: var(--text-tertiary);
  line-height: 1.2;
}

.app-btn strong {
  font-size: 0.9375rem;
  display: block;
}

/* --- Business Gifting --- */
.business-gifting {
  background: var(--green-dark);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  gap: 40px;
  color: var(--white);
}

.business-gifting-content {
  flex: 1;
}

.business-gifting-content h2 {
  color: var(--white);
  margin-bottom: 12px;
}

.business-gifting-content p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 24px;
}

/* --- FAQ --- */
.faq-item {
  border-bottom: 1px solid var(--border-light);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 1rem;
  color: var(--text-primary);
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--green-primary);
}

.faq-question svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition-base);
  color: var(--text-tertiary);
}

.faq-question.expanded svg {
  transform: rotate(180deg);
  color: var(--green-primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.faq-answer-inner {
  padding-bottom: 20px;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  line-height: 1.65;
}

/* --- eGift Section --- */
.egift-section {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: 40px;
}

.egift-links {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 16px;
}

.egift-link {
  color: var(--green-primary);
  font-weight: 500;
  font-size: 0.9375rem;
  transition: opacity var(--transition-fast);
}

.egift-link:hover {
  opacity: 0.8;
}

/* --- Category Carousel Section --- */
.category-section {
  margin-bottom: 48px;
}

.category-section h3 {
  font-size: 1.375rem;
  margin-bottom: 16px;
}

/* --- Responsive --- */
@media (max-width: 1200px) {
  .menu-layout {
    grid-template-columns: 240px 1fr;
    gap: 32px;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 1024px) {
  :root {
    --section-py: 60px;
  }

  .promo-split {
    grid-template-columns: 1fr;
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .business-gifting {
    flex-direction: column;
    text-align: center;
    padding: 32px;
  }
}

@media (max-width: 768px) {
  :root {
    --section-py: 48px;
    --section-px: 16px;
  }

  .header-nav, .header-actions .btn-outline, .header-actions .btn-primary {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .hero-section {
    padding: 48px 0;
    min-height: auto;
  }

  .hero-image {
    display: none;
  }

  .hero-content {
    max-width: 100%;
    text-align: center;
  }

  .hero-title {
    font-size: 2.25rem;
  }

  .hero-subtitle {
    margin-left: auto;
    margin-right: auto;
  }

  .how-it-works-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .tier-card {
    padding: 24px;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    max-height: none;
    border-bottom: 1px solid var(--border-light);
    padding-bottom: 16px;
    padding-right: 0;
  }

  .menu-sidebar-group {
    margin-bottom: 12px;
  }

  .menu-sidebar-group h3 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .menu-sidebar-group h3::after {
    content: '+';
    font-size: 1rem;
    font-weight: 400;
    color: var(--text-tertiary);
    transition: transform var(--transition-base);
  }

  .menu-sidebar-group.collapsed h3::after {
    content: '+';
  }

  .menu-sidebar-group.expanded h3::after {
    content: '−';
  }

  .menu-sidebar-group .sidebar-items {
    display: none;
  }

  .menu-sidebar-group.expanded .sidebar-items {
    display: block;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-accordion-btn {
    display: flex;
  }

  .footer-col-links {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow);
  }

  .footer-col-links.expanded {
    max-height: 500px;
  }

  .store-search {
    flex-direction: column;
  }

  .order-toggle {
    width: 100%;
  }

  .order-toggle-btn {
    flex: 1;
    text-align: center;
  }

  .redemption-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    bottom: 16px;
  }

  .cookie-banner-actions {
    width: 100%;
  }

  .cookie-banner-actions .btn {
    flex: 1;
  }

  .app-buttons {
    flex-direction: column;
    align-items: center;
  }

  .partner-card {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 1.875rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  .redemption-grid {
    grid-template-columns: 1fr;
  }

  .carousel-slide {
    flex: 0 0 75%;
  }

  .gift-card {
    width: 160px;
    height: 105px;
  }
}

/* --- Utility Classes --- */
.text-center { text-align: center; }
.text-left { text-align: left; }
.mx-auto { margin-left: auto; margin-right: auto; }
.mb-0 { margin-bottom: 0; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }
.mb-10 { margin-bottom: 40px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.w-full { width: 100%; }
.rounded-full { border-radius: var(--radius-full); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

@media (max-width: 768px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .hide-mobile { display: none; }
}
@media (min-width: 769px) {
  .hide-desktop { display: none; }
}
