.app-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-top: 24px;
}

.app-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.app-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.app-btn svg {
  width: 24px;
  height: 24px;
}

.app-btn span {
  text-align: left;
  font-size: 0.6875rem;
  color: var(--text-tertiary);
  line-height: 1.2;
}

.app-btn strong {
  font-size: 0.9375rem;
  display: block;
}

/* --- Business Gifting --- */
.business-gifting {
  background: var(--green-dark);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  gap: 40px;
  color: var(--white);
}

.business-gifting-content {
