.business-gifting-content h2 {
  color: var(--white);
  margin-bottom: 12px;
}

.business-gifting-content p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 24px;
}

/* --- FAQ --- */
.faq-item {
  border-bottom: 1px solid var(--border-light);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 1rem;
  color: var(--text-primary);
  transition: color var(--transition-fast);
